fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"module" => .{ .role = .@"decls", .slot = 1 },
        .@"struct" => .{ .role = .@"members", .slot = 2 },
        .@"enum" => .{ .role = .@"members", .slot = 2 },
        .@"errors" => .{ .role = .@"members", .slot = 2 },
        .@"generic_struct" => .{ .role = .@"members", .slot = 3 },
        .@"generic_enum" => .{ .role = .@"members", .slot = 3 },
        .@"match" => .{ .role = .@"arms", .slot = 2 },
        .@"alt_pattern" => .{ .role = .@"alts", .slot = 1 },
        .@"variant_pattern" => .{ .role = .@"bindings", .slot = 2 },
        .@"block" => .{ .role = .@"stmts", .slot = 1 },
        .@"captures" => .{ .role = .@"caps", .slot = 1 },
        .@"call" => .{ .role = .@"args", .slot = 2 },
        .@"builtin" => .{ .role = .@"args", .slot = 2 },
        .@"inst" => .{ .role = .@"args", .slot = 2 },
        .@"array" => .{ .role = .@"elems", .slot = 1 },
        .@"generic_inst" => .{ .role = .@"args", .slot = 2 },
        else => null,
    };
}

// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole program with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseProgram(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseProgram();
    return .{ .parser = p, .sexp = sexp };
}
